from pathlib import Path
p=Path('index.html'); s=p.read_text()
marker='/* WENIK HOME POLISH V6 */'
if marker in s: raise SystemExit('already patched')
css='''\n<style>\n/* WENIK HOME POLISH V6 */\n#home{background:linear-gradient(180deg,#120d22 0,#21132e 54%,#faf9fd 100%)!important;border-radius:28px 28px 0 0!important;padding-top:0!important}\n#home .wenikBrandPoster{margin:0!important;border-radius:26px!important;padding:22px 12px 24px!important;box-shadow:0 14px 34px rgba(0,0,0,.20)!important}\n#home .wenikBrandPoster:before,#home .wenikBrandPoster:after{height:90px!important;bottom:-34px!important}\n#home .wenikBrandMark{font-size:78px!important}.wenikBrandName{font-size:38px!important}.wenikBrandWin{margin-bottom:17px!important}.wenikBrandActions{margin-bottom:16px!important}.wenikBrandIcon{font-size:26px!important}.wenikBrandUrl{padding:7px 25px!important}\n#home .hero{background:transparent!important;border:0!important;box-shadow:none!important;color:#fff!important;padding:18px 24px 10px!important;margin:0!important;border-radius:0!important}\n#home .hero .eyebrow{color:#f09ce4!important;letter-spacing:4px!important}#home .hero h1,#home .hero h2{color:#fff!important}#home .hero p{color:#aaa3b6!important}\n#home .wenikMiniDash{margin:10px 16px 18px!important;border:0!important;border-radius:24px!important;background:linear-gradient(105deg,#7427ff,#e91cad 48%,#ff7a22 78%,#ffb51b)!important;box-shadow:0 12px 28px rgba(128,30,210,.25)!important;color:#fff!important;padding:16px 18px!important}\n#home .wenikMiniSlide b,#home .wenikMiniSlide span{color:#fff!important}\n#home .sectionTitle{color:#fff!important;padding:0 20px!important;margin-top:14px!important}#home .sectionTitle+*{margin-left:16px!important;margin-right:16px!important}\n#home .carousel{border-radius:25px!important;overflow:hidden!important;box-shadow:0 12px 28px rgba(0,0,0,.24)!important;background:#fff!important}\n#home .carousel img{object-fit:cover!important}\n#home .categoryRail,#home .categories{padding:4px 16px 18px!important;gap:9px!important}.categoryChip,.categoryBtn{border-radius:18px!important;box-shadow:0 6px 16px rgba(42,28,70,.08)!important}\n.bottomNav{border-radius:30px!important;margin:0 14px 10px!important;left:0!important;right:0!important;width:auto!important;box-shadow:0 10px 28px rgba(35,20,60,.18)!important}\n@media(max-width:640px){#home .wenikBrandPoster{padding:17px 8px 20px!important}.wenikBrandMark{font-size:66px!important}.wenikBrandName{font-size:33px!important}.wenikBrandIcon{font-size:22px!important}#home .hero{padding:15px 22px 8px!important}#home .wenikMiniDash{margin:8px 16px 16px!important;padding:14px 16px!important}#home .carousel{height:205px!important;max-height:205px!important}#home .carousel img{height:205px!important;max-height:205px!important}.bottomNav{margin-left:12px!important;margin-right:12px!important}}\n</style>\n'''
head=s.lower().rfind('</head>'); assert head>=0
s=s[:head]+css+s[head:]
p.write_text(s)
